      val r9 = compute_case_TRACK_TERMINAL_RESET(In_lifecycle, active_amount, active_attempt, active_product_id, active_request_id, lifecycle, api_dispatch_decision, api_shipment_instruction)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7 & r8 & r9
    }

