      val r1 = compute_CEP_T_Case (In_active_amount, In_active_attempt, In_active_product_id, In_active_request_id, In_lifecycle, active_amount, active_attempt, active_product_id, active_request_id, lifecycle, api_dispatch_decision, api_outcome_plan, api_shipment_instruction)

